        if (oItem.getSelected() && iPos < 0) { this._hierarchySelection.push(sId); }                                                                                                                                                                           
        if (!oItem.getSelected() && iPos >= 0) { this._hierarchySelection.splice(iPos, 1); }                                                                                                                                                                   
